mapper.select:
SELECT a.id, a.title, a.slug, a.summary, a.content, a.cover_image, a.category_id, a.user_id,
       a.view_count, a.comment_count, a.like_count, a.is_top, a.is_deleted, a.status, a.create_time, a.update_time,
       c.name as category_name
FROM blog_article a
LEFT JOIN blog_category c ON a.category_id = c.id

INNER JOIN blog_article_tag at ON a.id = at.article_id AND at.tag_id = #{tagId}

WHERE a.is_deleted = 0

    AND a.status = #{status}


    AND a.user_id = #{userId}


    AND (a.title LIKE CONCAT('%', #{keyword}, '%') OR a.summary LIKE CONCAT('%', #{keyword}, '%'))


    AND a.category_id = #{categoryId}


    AND DATE_FORMAT(a.create_time, '%Y-%m-%d') = #{date}

ORDER BY a.is_top DESC, a.create_time DESC

mapper.update:
UPDATE blog_article
title = #{title}, slug = #{slug}, summary = #{summary}, content = #{content}, cover_image = #{coverImage}, category_id = #{categoryId}, view_count = #{viewCount}, comment_count = #{commentCount}, like_count = #{likeCount}, is_top = #{isTop}, is_deleted = #{isDeleted}, status = #{status},
WHERE id = #{id}
